  /** Chicago complex dwell mid-2026 hrs */
  chicagoDwell2026Hrs: 26.2,
  /** 2019 Chicago complex dwell baseline hrs */
  chicagoDwell2019Hrs: 24.8,
  /** Correlation (quarterly): system speed vs rev/carload index, 2019???2026 */
