      : a.unitsPerMVacantSf - b.unitsPerMVacantSf,
  );
}

export function metrosByVacancy(desc = true): MetroRow[] {
  return [...METRO_ROWS].sort((a, b) =>
    desc ? b.vacancyPct - a.vacancyPct : a.vacancyPct - b.vacancyPct,
  );
}

