  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  COST_STACK,
  HEADLINE,
  METRO_ROWS,
  PIPELINE_PATH,
  REGION_MIX,
  REUSE_SOURCE_MIX,
  SCATTER_POINTS,
  SOURCE_NOTE,
  type Quadrant,
} from "@/data/office-vacancy-versus-conversion-pipelines-2026-data";

