            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={ladderData}
                margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis type="number" tick={{ fontSize: 11 }} />
                <YAxis
                  type="category"
                  dataKey="metro"
                  width={120}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(v: number | string) => [
                    typeof v === "number" ? v.toFixed(1) : v,
                    "Units / M vacant SF",
                  ]}
                />
                <Bar
                  dataKey="unitsPerMVacantSf"
                  name="Units / M vacant SF"
                  radius={[0, 4, 4, 0]}
                >
                  {ladderData.map((d) => (
                    <Cell key={d.metro} fill={QUAD_COLOR[d.quadrant]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-2 flex flex-wrap gap-3 text-xs text-slate-600">
            <span className="inline-flex items-center gap-1">
              <span
                className="inline-block h-2.5 w-2.5 rounded-full"
                style={{ background: COLORS.active }}
              />
              Active conversion
            </span>
            <span className="inline-flex items-center gap-1">
              <span
                className="inline-block h-2.5 w-2.5 rounded-full"
                style={{ background: COLORS.balanced }}
              />
              Balanced
            </span>
            <span className="inline-flex items-center gap-1">
              <span
                className="inline-block h-2.5 w-2.5 rounded-full"
                style={{ background: COLORS.stranded }}
              />
              Vacancy-stranded
            </span>
            <span className="inline-flex items-center gap-1">
              <span
                className="inline-block h-2.5 w-2.5 rounded-full"
                style={{ background: COLORS.tight }}
              />
              Tight market
            </span>
          </div>
        </ChartCard>
      ) : null}

      {panel === "scatter" ? (
        <ChartCard
          title="Vacancy rate ?? conversion intensity"
          subtitle={`Bubble size ??? pipeline units ?? panel corr vacancy???intensity ??? ${ANALYTICS.vacancyPipelineCorr}`}
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 4, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="vacancyPct"
                  name="Vacancy"
                  unit="%"
                  domain={[12, 28]}
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Office vacancy %",
                    position: "insideBottom",
                    offset: -4,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="unitsPerMVacantSf"
                  name="Intensity"
                  domain={[0, 240]}
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Units / M vacant SF",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="pipelineUnits" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v: number | string, name: string) => [
                    typeof v === "number" ? v.toLocaleString() : v,
                    name,
                  ]}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.metro ?? ""
                  }
                />
                <Scatter name="Metros" data={scatterData}>
                  {scatterData.map((p) => (
                    <Cell key={p.id} fill={QUAD_COLOR[p.quadrant]} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Upper-left = conversions without extreme vacancy ?? lower-right =
            vacant stock without a pipeline (stranded).
          </p>
        </ChartCard>
      ) : null}

      {panel === "path" ? (
        <ChartCard
          title="National pipeline path vs vacancy"
          subtitle="Start-of-year conversion units (left) against national vacancy % (right)"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={pathData} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis
                  yAxisId="units"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${Math.round(v / 1000)}k`}
                />
                <YAxis
                  yAxisId="vac"
                  orientation="right"
                  domain={[14, 22]}
                  tick={{ fontSize: 11 }}
                  unit="%"
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="units"
                  type="monotone"
                  dataKey="units"
                  name="Pipeline units"
                  fill={COLORS.pipeline}
                  fillOpacity={0.2}
                  stroke={COLORS.pipeline}
                  strokeWidth={2.5}
                />
                <Line
                  yAxisId="vac"
                  type="monotone"
                  dataKey="vacancyPct"
                  name="National vacancy %"
                  stroke={COLORS.vacancy}
                  strokeWidth={2.5}
                  dot={{ r: 4 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "costs" ? (
        <ChartCard
          title="Conversion vs ground-up cost per unit"
          subtitle="Estimated soft+hard midpoints ($k) ?? gap is the conversion discount before incentives"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={costData} margin={{ top: 8, right: 8, left: 0, bottom: 48 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="metro"
                  tick={{ fontSize: 10 }}
                  interval={0}
                  angle={-28}
                  textAnchor="end"
                  height={60}
                />
                <YAxis tick={{ fontSize: 11 }} unit="k" />
                <Tooltip />
                <Legend />
                <Bar
                  dataKey="conversion"
                  name="Conversion $/unit (k)"
                  fill={COLORS.cost}
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="groundUp"
                  name="Ground-up $/unit (k)"
                  fill={COLORS.ground}
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "mix" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Adaptive-reuse source mix"
            subtitle="Share of future reuse projects by origin building type (start-2026)"
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {pieData.map((d, i) => (
                      <Cell key={d.name} fill={COLORS.pie[i % COLORS.pie.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v: number | string) => [`${v}%`, "Share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Regional pipeline share"
            subtitle="National conversion units by Census region ?? bars = share %"
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={REGION_MIX} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="region" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="pipelineSharePct"
                    name="Pipeline share %"
                    stroke={COLORS.intensity}
                    fill={COLORS.intensity}
                    fillOpacity={0.35}
                  />
                  <Line
                    type="monotone"
                    dataKey="avgVacancyPct"
                    name="Avg vacancy %"
                    stroke={COLORS.vacancy}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

