const raw = fs.readFileSync("src/data/posts.ts", "utf8");
const needle = 'id: "office-vacancy-versus-conversion-pipelines-2026"';
const i = raw.indexOf(needle);
const cs = raw.indexOf("content: `", i) + "content: `".length;
// find closing backtick that ends the template before next post object
let ce = cs;
while (ce < raw.length) {
  if (raw[ce] === "`" && raw.slice(ce, ce + 6) === "`,\n  {") break;
  ce++;
}
const c = raw.slice(cs, ce);
const words = c.trim().split(/\s+/).filter(Boolean).length;
const h2 = (c.match(/^## /gm) || []).length;
console.log(JSON.stringify({ words, h2, len: c.length }));

