        </div>
        <div className="flex flex-wrap gap-3">
          <label className="flex flex-col gap-1 text-xs font-medium text-slate-600">
            Focus panel
            <select
              className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900"
